messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 200;
        const FINISH_LINE_Z = -TRACK_LENGTH / 2;
        const START_LINE_Z = TRACK_LENGTH / 2;
        const RACE_DURATION = 6.0; // Seconds for one full loop
        const RESET_DURATION = 1.0; // Seconds to hold/reset at end

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 300);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(400, 400);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x2a9d8f });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1;
        ground.receiveShadow = true;
        scene.add(ground);

        // Road
        const roadGeo = new THREE.PlaneGeometry(40, 400);
        const roadMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const road = new THREE.Mesh(roadGeo, roadMat);
        road.rotation.x = -Math.PI / 2;
        road.receiveShadow = true;
        scene.add(road);

        // Lane Markers
        const lineGeo = new THREE.PlaneGeometry(0.5, 400);
        const lineMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const line = new THREE.Mesh(lineGeo, lineMat);
        line.rotation.x = -Math.PI / 2;
        line.position.y = 0.01;
        scene.add(line);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(40, 4);
        // Create a simple checkerboard texture programmatically
        const canvas = document.createElement('canvas');
        canvas.width = 64; canvas.height = 64;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#ffffff'; ctx.fillRect(0,0,64,64);
        ctx.fillStyle = '#000000';
        ctx.fillRect(0,0,32,32); ctx.fillRect(32,32,32,32);
        const texture = new THREE.CanvasTexture(canvas);
        texture.magFilter = THREE.NearestFilter;

        const finishMat = new THREE.MeshBasicMaterial({ map: texture });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.02, FINISH_LINE_Z);
        scene.add(finishLine);

        // Finish Line Pillar
        const pillarGeo = new THREE.BoxGeometry(2, 10, 2);
        const pillarMat = new THREE.MeshStandardMaterial({ color: 0xaaaaaa });
        const pillar = new THREE.Mesh(pillarGeo, pillarMat);
        pillar.position.set(22, 5, FINISH_LINE_Z);
        pillar.castShadow = true;
        scene.add(pillar);

        const bannerGeo = new THREE.BoxGeometry(2, 2, 10);
        const bannerMat = new THREE.MeshStandardMaterial({ color: 0xff0000 });
        const banner = new THREE.Mesh(bannerGeo, bannerMat);
        banner.position.set(22, 8, FINISH_LINE_Z);
        scene.add(banner);


        // --- Car Factory ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(2, 1, 4.5);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.3, metalness: 0.7 });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 1;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.8, 0.8, 2.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.1 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = 1.8;
            cabin.position.z = -0.3;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x222222 });

            const positions = [
                { x: -1.1, z: 1.5 }, { x: 1.1, z: 1.5 },
                { x: -1.1, z: -1.5 }, { x: 1.1, z: -1.5 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.6, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Spoiler
            const spoilerGeo = new THREE.BoxGeometry(2, 0.2, 0.8);
            const spoiler = new THREE.Mesh(spoilerGeo, chassisMat);
            spoiler.position.set(0, 1.8, 2.2);
            carGroup.add(spoiler);

            const spoilerStandGeo = new THREE.BoxGeometry(0.2, 0.5, 0.2);
            const stand1 = new THREE.Mesh(spoilerStandGeo, chassisMat);
            stand1.position.set(0.6, 1.5, 2.2);
            carGroup.add(stand1);
            const stand2 = new THREE.Mesh(spoilerStandGeo, chassisMat);
            stand2.position.set(-0.6, 1.5, 2.2);
            carGroup.add(stand2);

            return carGroup;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);

        // Initial Position
        redCar.position.set(-7, 0, START_LINE_Z);
        blueCar.position.set(7, 0, START_LINE_Z);

        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---
        const clock = new THREE.Clock();
        let raceTime = 0;
        let state = 'RACING'; // RACING, FINISHED

        // Helper for smooth easing
        // Blue: Starts fast, slows down slightly
        // Red: Starts slow, accelerates massively to overtake
        function getBluePosition(t) {
            // t is 0 to 1
            // Ease out cubic
            return START_LINE_Z - (START_LINE_Z - FINISH_LINE_Z) * (1 - Math.pow(1 - t, 3));
        }

        function getRedPosition(t) {
            // t is 0 to 1
            // Ease in quartic
            return START_LINE_Z - (START_LINE_Z - FINISH_LINE_Z) * (Math.pow(t, 4));
        }

        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();

            if (state === 'RACING') {
                raceTime += delta;
                const progress = Math.min(raceTime / RACE_DURATION, 1.0);

                // Update positions
                blueCar.position.z = getBluePosition(progress);
                redCar.position.z = getRedPosition(progress);

                // Add slight vibration/lean
                redCar.rotation.z = Math.sin(raceTime * 10) * 0.02;
                blueCar.rotation.z = Math.sin(raceTime * 10 + 1) * 0.02;

                if (progress >= 1.0) {
                    state = 'FINISHED';
                    raceTime = 0;
                }
            } else if (state === 'FINISHED') {
                raceTime += delta;
                // Reset after a pause
                if (raceTime > RESET_DURATION) {
                    state = 'RACING';
                    raceTime = 0;
                    redCar.rotation.z = 0;
                    blueCar.rotation.z = 0;
                }
            }

            // Camera Logic
            // Find the leading car
            // Since Z decreases towards finish, lower Z is ahead.
            // We want to look at the car with the lowest Z.
            const leadingZ = Math.min(redCar.position.z, blueCar.position.z);
            const trailingZ = Math.max(redCar.position.z, blueCar.position.z);

            // Center camera between them, but biased towards the leader
            const camZ = leadingZ - 25; // Camera stays behind the leader
            const camY = 8;
            const camX = 0; // Center X

            // Smoothly interpolate camera position
            camera.position.z += (camZ - camera.position.z) * 0.1;
            camera.position.y += (camY - camera.position.y) * 0.1;
            camera.lookAt(0, 1, leadingZ + 20); // Look slightly ahead of the leader

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
